def write_lines(path, lines) = File.write(path, lines.join("\n") + "\n")
      w, b = run[:net].layer_values(run[:theta], layer)
      w.each { |row| final << "W #{row.map { |v| real(v) }.join(' ')}" }
  write_lines('output/final_weights.txt', final)
  def real(value, places = 4)
    text = format("%.#{places}f", value)
    text.start_with?('-') && text.to_f.zero? ? text[1..] : text
  def layer_values(theta, layer)
    [theta[layer[:weight_start]...layer[:weight_end]].each_slice(layer[:inputs]).to_a,
     theta[layer[:bias_start]...layer[:bias_end]]]
